import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# CUDA kernel for matrix multiplication (C = A.T @ B.T)
__global__ void gemm_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    int m = blockIdx.y * blockDim.y + threadIdx.y;
    int n = blockIdx.x * blockDim.x + threadIdx.x;
    if (m < M && n < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            sum += A[k * M + m] * B[n * K + k];
        }
        C[m * N + n] = sum;
    }
}


custom_matmul_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void gemm_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    int m = blockIdx.y * blockDim.y + threadIdx.y;
    int n = blockIdx.x * blockDim.x + threadIdx.x;
    if (m < M && n < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            sum += A[k * M + m] * B[n * K + k];
        }
        C[m * N + n] = sum;
    }
}

torch::Tensor custom_matmul_cuda(torch::Tensor a, torch::Tensor b) {
    auto a_f = a.to(torch.float32()).contiguous();
    auto b_f = b.to(torch.float32()).contiguous();

    int K = a_f.size(0);
    int M = a_f.size(1);
    int N = b_f.size(0);

    auto C = torch::zeros({M, N}, torch::float());
    C = C.to(a.device());

    float* A_ptr = a_f.data_ptr<float>();
    float* B_ptr = b_f.data_ptr<float>();
    float* C_ptr = C.data_ptr<float>();

    int blockSizeX = 256;
    int blockSizeY = 256;
    int num_n_blocks = (N + blockSizeX - 1) / blockSizeX;
    int num_m_blocks = (M + blockSizeY - 1) / blockSizeY;

    gemm_kernel<<<num_n_blocks, num_m_blocks, blockSizeX, blockSizeY>>>(
        A_ptr, B_ptr, C_ptr, M, N, K
    );

    return C;
}
"""

custom_matmul_cpp_source = (
    "torch::Tensor custom_matmul_cuda(torch::Tensor a, torch::Tensor b);"
)


custom_matmul = load_inline(
    name="custom_matmul_cuda",
    cpp_sources=custom_matmul_cpp_source,
    cuda_sources=custom_matmul_cuda_source,
    functions=["custom_matmul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.custom_matmul_cuda = custom_matmul

    def forward(self, A, B):
        return self.custom_matmul_cuda(A, B)
